60: /// Starts the HTTP and WebSocket server with explicit pre-existing shared state.
61: pub async fn start_server_with_state(
62:     config: ServerConfig,
63:     state: AppState,
64: ) -> Result<(), ServerError> {
65:     let addr = format!("{}:{}", config.host, config.port);
66:     let listener = tokio::net::TcpListener::bind(&addr).await?;
67:     tracing::info!("OpenFlightReader server listening on http://{}", addr);
68: 
69:     let app = build_app(state);
70: 
71:     axum::serve(listener, app)
72:         .with_graceful_shutdown(shutdown_signal())
73:         .await?;
74: 
75:     tracing::info!("Server shut down gracefully");
76:     Ok(())
77: }
78: 
79: async fn shutdown_signal() {
80:     let _ = tokio::signal::ctrl_c().await;
81:     tracing::info!("Received Ctrl-C signal, initiating graceful shutdown...");
82: }
