1: //! Embedded offline static asset serving with air-gapped Content-Security-Policy.
2: 
3: use axum::{
4:     http::{header, HeaderValue, StatusCode, Uri},
5:     response::{IntoResponse, Response},
6: };
7: use rust_embed::RustEmbed;
8: 
9: /// Static assets embedded directly into the server binary at compile time.
10: #[derive(RustEmbed)]
11: #[folder = "assets/"]
12: pub struct EmbeddedAssets;
13: 
14: /// Authoritative strict air-gapped Content-Security-Policy header value.
15: pub const CSP_VALUE: &str = "default-src 'self' 'unsafe-inline' data:; connect-src 'self' ws:; img-src 'self' data: blob:; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; object-src 'none'; base-uri 'self'";
16: 
17: /// Serves compile-time embedded frontend assets from memory.
18: pub async fn static_handler(uri: Uri) -> Response {
19:     let raw_path = uri.path();
20: 
21:     // Directory traversal security check
22:     if raw_path.contains("..") || raw_path.contains("%2e") || raw_path.contains("%2E") {
23:         return (StatusCode::NOT_FOUND, "Not Found").into_response();
24:     }
25: 
26:     let mut path = raw_path.trim_start_matches('/').to_string();
27:     if path.is_empty() {
28:         path = "index.html".to_string();
29:     }
30: 
31:     match EmbeddedAssets::get(&path) {
32:         Some(content) => {
33:             let mime = if path.ends_with(".js") {
34:                 "application/javascript; charset=utf-8".to_string()
35:             } else if path.ends_with(".css") {
36:                 "text/css; charset=utf-8".to_string()
37:             } else if path.ends_with(".html") {
38:                 "text/html; charset=utf-8".to_string()
39:             } else {
40:                 mime_guess::from_path(&path)
41:                     .first_or_octet_stream()
42:                     .to_string()
43:             };
44: 
45:             let mut response = (StatusCode::OK, content.data).into_response();
46:             let headers = response.headers_mut();
47: 
48:             // MIME type
49:             if let Ok(val) = HeaderValue::from_str(&mime) {
50:                 headers.insert(header::CONTENT_TYPE, val);
51:             }
52: 
53:             // Air-Gap Strict Content-Security-Policy
54:             headers.insert(
55:                 header::HeaderName::from_static("content-security-policy"),
56:                 HeaderValue::from_static(CSP_VALUE),
57:             );
58: 
59:             // Security Hardening Headers
60:             headers.insert(
61:                 header::X_CONTENT_TYPE_OPTIONS,
62:                 HeaderValue::from_static("nosniff"),
63:             );
64:             headers.insert(header::X_FRAME_OPTIONS, HeaderValue::from_static("DENY"));
65:             headers.insert(
66:                 header::HeaderName::from_static("referrer-policy"),
67:                 HeaderValue::from_static("no-referrer"),
68:             );
69: 
70:             // Caching
71:             let cache_control = if path == "index.html" {
72:                 "no-cache, must-revalidate"
73:             } else {
74:                 "public, max-age=3600"
75:             };
76:             headers.insert(
77:                 header::CACHE_CONTROL,
78:                 HeaderValue::from_static(cache_control),
79:             );
80: 
81:             response
82:         }
83:         None => (StatusCode::NOT_FOUND, "404 Not Found").into_response(),
84:     }
85: }
