#[tokio::test]
async fn test_ws_broadcast_channel_overflow_behavior() {
    let dataset = mock_canonical_dataset();
    let state = AppState::new_with_dataset(dataset);
    let app = build_app(state.clone());

    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();

    let server_task = tokio::spawn(async move {
        axum::serve(listener, app).await.unwrap();
    });

    let ws_url = format!("ws://{}/api/v1/ws", addr);

    // Client Slow connects
    let (mut slow_stream, _) = connect_async(&ws_url).await.unwrap();

    // Client Fast connects
    let (mut fast_stream, _) = connect_async(&ws_url).await.unwrap();

    // Send 150 messages directly to the broadcast channel (exceeding capacity 128)
    // while slow_stream is not actively reading.
    for i in 0..150 {
        let _ = state.ws_broadcaster.send(WsServerMessage::Pong);
    }

    // Now let slow_stream attempt to read:
    // With `while let Ok(msg) = broadcast_rx.recv().await`, RecvError::Lagged
    // causes the send_task to terminate immediately!
    let next_msg = tokio::time::timeout(std::time::Duration::from_millis(500), slow_stream.next()).await;

    // Check whether the stream closed (returned None or Close frame)
    println!("Slow stream received after overflow: {:?}", next_msg);

    server_task.abort();
}
"

